def load_articles(text: str) -> tuple[int, int, list[dict]]:
    start = text.index(START_MARKER) + len(START_MARKER)
    end = text.index(END_MARKER, start) + 2
    return start, end, json.loads(text[start:end])


def main() -> None:
    text = SOURCE.read_text(encoding="utf-8")
    start, end, articles = load_articles(text)
    by_slug = {article["slug"]: article for article in articles}
    for article in NEW_ARTICLES:
        by_slug[article["slug"]] = article
    ordered_slugs = [article["slug"] for article in articles]
    for article in NEW_ARTICLES:
        if article["slug"] not in ordered_slugs:
            ordered_slugs.append(article["slug"])
    updated = [by_slug[slug] for slug in ordered_slugs]
    serialized = json.dumps(updated, ensure_ascii=False, indent=2)
    SOURCE.write_text(text[:start] + serialized + text[end:] , encoding="utf-8")
    print(f"Published {len(NEW_ARTICLES)} original articles; total collection: {len(updated)}")


if __name__ == "__main__":
    main()
